/**
 * Bindings read from `cloudflare:workers`. Kept here rather than in the
 * generated worker-configuration.d.ts (regenerated by `pnpm cf-typegen`,
 * which drops manual edits) and merged into the generated empty
 * `Cloudflare.Env`.
 */
declare namespace Cloudflare {
  interface Env {
    ASSETS: Fetcher
  }
}
